```
import { createBankedFreeCamera } from "@babylonjs/lite";
import type { FreeCamera } from "@babylonjs/lite";

type Vec = { x: number; y: number; z: number };

export interface ChaseCamera {
  camera: FreeCamera;
  bank(up: Vec): void;
}

const EPS = 1e-7;

function isFiniteVec(v: Vec): boolean {
  return Number.isFinite(v.x) && Number.isFinite(v.y) && Number.isFinite(v.z);
}

function length(v: Vec): number {
  return Math.hypot(v.x, v.y, v.z);
}

function normalize(v: Vec): Vec | null {
  const len = length(v);
  if (len <= EPS || !Number.isFinite(len)) return null;
  return { x: v.x / len, y: v.y / len, z: v.z / len };
}

function dot(a: Vec, b: Vec): number {
  return a.x * b.x + a.y * b.y + a.z * b.z;
}

function orthoUp(up: Vec, forward: Vec): Vec | null {
  const d = dot(up, forward);
  const out = { x: up.x - forward.x * d, y: up.y - forward.y * d, z: up.z - forward.z * d };
  return normalize(out);
}

function initialUp(eye: Vec, target: Vec): Vec {
  const forward = normalize({ x: target.x - eye.x, y: target.y - eye.y, z: target.z - eye.z });
  if (forward) {
    const up = orthoUp({ x: 0, y: 1, z: 0 }, forward);
    if (up) return up;
    const fallbackX = orthoUp({ x: 1, y: 0, z: 0 }, forward);
    if (fallbackX) return fallbackX;
    const fallbackZ = orthoUp({ x: 0, y: 0, z: 1 }, forward);
    if (fallbackZ) return fallbackZ;
  }
  return { x: 0, y: 1, z: 0 };
}

export function createChaseCamera(eye: Vec, target: Vec): ChaseCamera {
  const camera = createBankedFreeCamera(
    { x: eye.x, y: eye.y, z: eye.z },
    { x: target.x, y: target.y, z: target.z },
    initialUp(eye, target)
  );

  return {
    camera,
    bank(up: Vec) {
      if (!isFiniteVec(up)) return;
      const pos = camera.position;
      const tgt = camera.target;
      if (!isFiniteVec(pos) || !isFiniteVec(tgt)) return;
      const forward = normalize({ x: tgt.x - pos.x, y: tgt.y - pos.y, z: tgt.z - pos.z });
      if (!forward) return;
      const unitUp = normalize(up);
      if (!unitUp) return;
      const bankedUp = orthoUp(unitUp, forward);
      if (!bankedUp) return;
      const uv = camera.upVector; // but camera typed FreeCamera doesn't have upVector
    }
  };
}
